15	/**
16	 * Resolves the EFFECTIVE registration date and rolls it onto a business day.
17	 *
18	 * <p>The effective date is the one supplied in the request, or the server's current date when the
19	 * request omits it. A supplied date later than the server's current date is rejected with 400 via
20	 * {@link MethodArgumentNotValidException} — an owner cannot be registered in the future. Otherwise,
21	 * when that date lands on a Saturday or Sunday it is rolled forward to the next Monday. The adjusted
22	 * date is published as a variable so every later step derives from the same value: the daily
23	 * create-limit counts owners per adjusted business day, {@link BuildOwner} stores it as the owner's
24	 * {@code registrationDate}, and {@link AssignMembershipNumber} takes the membership number's year
25	 * segment from it.
26	 *
27	 * <p>Runs before {@link EnsureDailyOwnerLimit} so the limit is checked against the adjusted date.
28	 */
29	public class NormalizeRegistrationDate {
30	
31	    private static final Method SERVICE_METHOD;
32	
33	    static {
34	        try {
35	            SERVICE_METHOD = NormalizeRegistrationDate.class.getMethod("service", OwnerFieldsDto.class, Out.class);
36	        }
37	        catch (NoSuchMethodException ex) {
38	            throw new ExceptionInInitializerError(ex);
39	        }
40	    }
41	
42	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate)
43	            throws MethodArgumentNotValidException {
44	        LocalDate supplied = request.getRegistrationDate();
45	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
46	            BindingResult binding = new BeanPropertyBindingResult(request, "ownerFieldsDto");
47	            binding.rejectValue("registrationDate", "FutureDate",
48	                "registration date must not be later than the current date");
49	            throw new MethodArgumentNotValidException(new MethodParameter(SERVICE_METHOD, 0), binding);
50	        }
51	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
52	        registrationDate.set(toBusinessDay(effective));
53	    }
54	
55	    private static LocalDate toBusinessDay(LocalDate date) {
56	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
57	            date = date.plusDays(1);
58	        }
59	        return date;
60	    }
61	}
